<?php
namespace App\Entity;
use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity]
class Emploi { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne] private ?Candidat $candidat=null; #[ORM\Column(type:'date',nullable:true)] private ?\DateTimeInterface $dateInsertion=null; #[ORM\Column(length:180,nullable:true)] private ?string $employeur=null; #[ORM\Column(length:120,nullable:true)] private ?string $poste=null; #[ORM\Column(length:30)] private string $statut='EN_RECHERCHE'; #[ORM\Column(type:'text',nullable:true)] private ?string $observations=null; public function getId():?int{return $this->id;} public function getCandidat():?Candidat{return $this->candidat;} public function setCandidat(?Candidat $v):self{$this->candidat=$v;return $this;} public function getDateInsertion():?\DateTimeInterface{return $this->dateInsertion;} public function setDateInsertion(?\DateTimeInterface $v):self{$this->dateInsertion=$v;return $this;} public function getEmployeur():?string{return $this->employeur;} public function setEmployeur(?string $v):self{$this->employeur=$v;return $this;} public function getPoste():?string{return $this->poste;} public function setPoste(?string $v):self{$this->poste=$v;return $this;} public function getStatut():string{return $this->statut;} public function setStatut(string $v):self{$this->statut=$v;return $this;} public function getObservations():?string{return $this->observations;} public function setObservations(?string $v):self{$this->observations=$v;return $this;} }
